// Götterdämmerung act-1; original German and machine-assisted English working text.
export const gotterdammerungAct1Scenes = [{"number":1,"originalHeading":"ERSTE SZENE","translatedHeading":"First Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Die Halle der Gibichungen am Rhein","translatedTitle":"The Hall of the Gibichungs on the Rhine","participants":[],"sourceStartIndex":0,"sourceLineCount":2,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die Halle der Gibichungen am Rhein\nDiese ist dem Hintergrunde zu ganz offen; den Hintergrund selbst nimmt ein freier Uferraum bis zum Flusse hin ein; felsige Anhöhen umgrenzen das Ufer","translation":"The Hall of the Gibichungs on the Rhine\nThis is completely open to the background; the background itself is occupied by an open shoreline stretching to the river; rocky hills border the shore.","literalText":true,"sourceStartIndex":0,"sourceLineCount":2}]}]},{"number":2,"originalHeading":"ERSTE SZENE","translatedHeading":"Second Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Nun hör', Hagen, sage mir, Held:","translatedTitle":"Now listen, Hagen, tell me, hero:","participants":["GUNTHER","HAGEN","GUTRUNE"],"sourceStartIndex":0,"sourceLineCount":73,"turns":[{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Nun hör', Hagen, sage mir, Held:\nsitz' ich herrlich am Rhein,\nGunther zu Gibichs Ruhm?","translation":"Now listen, Hagen, tell me, hero:\nI sit wonderfully by the Rhine,\nGunther to Gibich's glory?","literalText":true,"sourceStartIndex":0,"sourceLineCount":3},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Dich echt genannten acht' ich zu neiden:\ndie beid' uns Brüder gebar,\nFrau Grimhild' hiess mich's begreifen.","translation":"I envy you, the one you truly are:\nwho bore us two brothers,\n'Frau Grimhild' told me to understand.","literalText":true,"sourceStartIndex":3,"sourceLineCount":3},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Dich neide ich: nicht neide mich du!\nErbt' ich Erstlingsart,\nWeisheit ward dir allein:\nHalbbrüderzwist bezwang sich nie besser.\nDeinem Rat nur red' ich Lob,\nfrag' ich dich nach meinem Ruhm.","translation":"I envy you: you don't envy me!\nIf I inherit the first type of offspring,\nWisdom was yours alone:\nThe feud between half-brothers was never better resolved.\nI praise only your advice,\nI ask you about my fame.","literalText":true,"sourceStartIndex":6,"sourceLineCount":6},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"So schelt' ich den Rat,\nda schlecht noch dein Ruhm;\ndenn hohe Güter weiss ich,\ndie der Gibichung noch nicht gewann.","translation":"So I rebuke the council,\nYour fame is still bad;\nFor I know high values,\nwhich Gibichung has not yet won.","literalText":true,"sourceStartIndex":12,"sourceLineCount":4},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Verschwiegest du sie,\nso schelt' auch ich.","translation":"Did you keep them secret?\nI scold them too.","literalText":true,"sourceStartIndex":16,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"In sommerlich reifer Stärke\nseh' ich Gibichs Stamm,\ndich, Gunther, unbeweibt,\ndich, Gutrun', ohne Mann.","translation":"In summery, ripe strength\nI see Gibich's tribe,\nyou, Gunther, unmarried,\nyou, Gutrun, without a man.","literalText":true,"sourceStartIndex":18,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther und Gutrune sind in schweigendes Sinnen verloren","translation":"Gunther and Gutrune are lost in silent contemplation.","literalText":true,"sourceStartIndex":22,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Wen rätst du nun zu frein,\ndass unsrem Ruhm' es fromm'?","translation":"Who would you advise to marry?\nthat it is beneficial to our glory?","literalText":true,"sourceStartIndex":23,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ein Weib weiss ich,\ndas herrlichste der Welt:\nauf Felsen hoch ihr Sitz;\nein Feuer umbrennt ihren Saal;\nnur wer durch das Feuer bricht,\ndarf Brünnhildes Freier sein.","translation":"I know one woman,\nthe most wonderful thing in the world:\nTheir seat is high on a rock;\na fire surrounds their hall;\nOnly those who break through the fire,\nBrünnhilde's suitor may be.","literalText":true,"sourceStartIndex":25,"sourceLineCount":6},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Vermag das mein Mut zu bestehn?","translation":"Can my courage withstand this?","literalText":true,"sourceStartIndex":31,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Einem Stärkren noch ist's nur bestimmt.","translation":"It is only destined for one stronger person.","literalText":true,"sourceStartIndex":32,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Wer ist der streitlichste Mann?","translation":"Who is the most argumentative man?","literalText":true,"sourceStartIndex":33,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Siegfried, der Wälsungen Spross:\nder ist der stärkste Held.\nEin Zwillingspaar,\nvon Liebe bezwungen,\nSiegmund und Sieglinde,\nzeugten den echtesten Sohn.\nDer im Walde mächtig erwuchs,\nden wünsch' ich Gutrun' zum Mann.","translation":"Siegfried, the Wälsung scion:\nHe is the strongest hero.\nA pair of twins,\nconquered by love\nSiegmund and Sieglinde,\nThey begot the truest son.\nThe one that grew mightily in the forest,\nI wish Gutrun to become my husband.","literalText":true,"sourceStartIndex":34,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"schüchtern beginnend","translation":"shyly beginning","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Welche Tat schuf er so tapfer,\ndass als herrlichster Held er genannt?","translation":"What deed did he perform so bravely?\nthat he was called the most glorious hero?","literalText":true,"sourceStartIndex":43,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Vor Neidhöhle den Niblungenhort\nbewachte ein riesiger Wurm:\nSiegfried schloss ihm den freislichen Schlund,\nerschlug ihn mit siegendem Schwert.\nSolch ungeheurer Tat\nenttagte des Helden Ruhm.","translation":"Before the Nibelung Cave\nguarded by a giant worm:\nSiegfried closed his free-spirited throat,\nslew him with a victorious sword.\nSuch a monstrous act\nThe hero's glory was extinguished.","literalText":true,"sourceStartIndex":45,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in Nachsinnen","translation":"in contemplation","literalText":true,"sourceStartIndex":51,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Vom Niblungenhort vernahm ich:\ner birgt den neidlichsten Schatz?","translation":"From the Nibelung hoard I heard:\nDoes it hold the most enviable treasure?","literalText":true,"sourceStartIndex":52,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Wer wohl ihn zu nützen wüsst',\ndem neigte sich wahrlich die Welt.","translation":"Who would know how to use him?\nThe world truly bowed down to him.","literalText":true,"sourceStartIndex":54,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Und Siegfried hat ihn erkämpft?","translation":"And Siegfried fought for it?","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Knecht sind die Niblungen ihm.","translation":"The Nibelungs are his servants.","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Und Brünnhild' gewänne nur er?","translation":"And only he would win Brünnhilde?","literalText":true,"sourceStartIndex":58,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Keinem andren wiche die Brunst.","translation":"The lust yielded to no other.","literalText":true,"sourceStartIndex":59,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"unwillig sich vom Sitze erhebend","translation":"reluctantly rising from his seat","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Wie weckst du Zweifel und Zwist!\nWas ich nicht zwingen soll,\ndarnach zu verlangen machst du mir Lust?","translation":"How do you sow doubt and discord?\nWhat I shouldn't force,\nDoes demanding that excite me?","literalText":true,"sourceStartIndex":61,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er schreitet bewegt in der Halle auf und ab. Hagen, ohne seinen Sitz zu verlassen, hält Gunther, als dieser wieder in seine Nähe kommt, durch einen geheimnisvollen Wink fest","translation":"He paces the hall, visibly moved. Hagen, without leaving his seat, stops Gunther with a mysterious gesture as he approaches him again.","literalText":true,"sourceStartIndex":64,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Brächte Siegfried die Braut dir heim,\nwär' dann nicht Brünnhilde dein?","translation":"If Siegfried brought the bride home to you,\nWouldn't Brünnhilde be yours then?","literalText":true,"sourceStartIndex":65,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wendet sich wieder zweifelnd und unmutig ab","translation":"turns away again, doubting and disgruntled","literalText":true,"sourceStartIndex":67,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Was zwänge den frohen Mann,\nfür mich die Braut zu frein?","translation":"What compels the happy man,\nTo woo the bride for me?","literalText":true,"sourceStartIndex":68,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wie vorher","translation":"as before","literalText":true,"sourceStartIndex":70,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ihn zwänge bald deine Bitte,\nbänd' ihn Gutrun' zuvor.","translation":"Your request would soon compel him to comply.\nbund' ihn Gutrun' vor.","literalText":true,"sourceStartIndex":71,"sourceLineCount":2}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Du Spötter, böser Hagen!","translatedTitle":"You mocker, wicked Hagen!","participants":["GUTRUNE","HAGEN","GUNTHER","SIEGFRIEDS STIMME"],"sourceStartIndex":73,"sourceLineCount":50,"turns":[{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Du Spötter, böser Hagen!\nWie sollt' ich Siegfried binden?\nIst er der herrlichste Held der Welt,\nder Erde holdeste Frauen\nfriedeten längst ihn schon.","translation":"You mocker, wicked Hagen!\nHow should I bind Siegfried?\nIs he the most glorious hero in the world?\nEarth's fairest women\nThey had long since made peace with him.","literalText":true,"sourceStartIndex":73,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sehr vertraulich zu Gutrune hinneigend","translation":"very confidential, tending towards Gutrune","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Gedenk' des Trankes im Schrein;","translation":"Remember the drink in the shrine;","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heimlicher","translation":"secretive","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"vertraue mir, der ihn gewann:\nden Helden, des du verlangst,\nbindet er liebend an dich.","translation":"Trust me, the one who won it:\nthe hero you demand,\nHe binds you lovingly.","literalText":true,"sourceStartIndex":81,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther ist wieder an den Tisch getreten und hört, auf ihn gelehnt, jetzt aufmerksam zu","translation":"Gunther has returned to the table and, leaning against it, is now listening attentively.","literalText":true,"sourceStartIndex":84,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Träte nun Siegfried ein,\ngenöss' er des würzigen Tranks,\ndass vor dir ein Weib er ersah,\ndass je ein Weib ihm genaht,\nvergessen müsst' er des ganz.\nNun redet: wie dünkt euch Hagens Rat?","translation":"If Siegfried were to enter now,\nhe enjoyed the spicy drink,\nthat he saw a woman before you,\nthat a woman ever approached him,\nHe would have to forget all of that.\nNow speak: what do you think of Hagen's advice?","literalText":true,"sourceStartIndex":85,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lebhaft auffahrend","translation":"lively and fast-moving","literalText":true,"sourceStartIndex":91,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Gepriesen sei Grimhild',\ndie uns den Bruder gab!","translation":"Praised be Grimhild,\nwho gave us our brother!","literalText":true,"sourceStartIndex":92,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Möcht' ich Siegfried je ersehn!","translation":"I wish I could ever see Siegfried!","literalText":true,"sourceStartIndex":94,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Wie suchten wir ihn auf?","translation":"How did we find him?","literalText":true,"sourceStartIndex":95,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ein Horn auf dem Theater klingt aus dem Hintergrunde von links her. Hagen lauscht","translation":"A horn sounds from the back of the theater, coming from the left. Hagen listens.","literalText":true,"sourceStartIndex":96,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Jagt er auf Taten wonnig umher,\nzum engen Tann wird ihm die Welt:\nwohl stürmt er in rastloser Jagd\nauch zu Gibichs Strand an den Rhein.","translation":"Does he blissfully hunt about in pursuit of deeds?\nThe world becomes a narrow fir forest to him:\nHe probably storms on in a restless hunt.\nalso to Gibich's beach on the Rhine.","literalText":true,"sourceStartIndex":97,"sourceLineCount":4},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Willkommen hiess' ich ihn gern!","translation":"I was happy to welcome him!","literalText":true,"sourceStartIndex":101,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Horn auf dem Theater, näher, aber immer noch fern. Beide lauschen","translation":"A horn sounds in the theater, closer, but still far away. Both are listening.","literalText":true,"sourceStartIndex":102,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Vom Rhein ertönt das Horn.","translation":"The horn sounds from the Rhine.","literalText":true,"sourceStartIndex":103,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ist an das Ufer gegangen, späht den Fluss hinab und ruft zurück","translation":"went to the bank, peered down the river and called back","literalText":true,"sourceStartIndex":104,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"In einem Nachen Held und Ross!\nDer bläst so munter das Horn!","translation":"In a boat, hero and horse!\nHe's blowing that horn so merrily!","literalText":true,"sourceStartIndex":105,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther bleibt auf halbem Wege lauschend zurück","translation":"Gunther stays behind halfway, listening intently.","literalText":true,"sourceStartIndex":107,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ein gemächlicher Schlag,\nwie von müssiger Hand,\ntreibt jach den Kahn wider den Strom;\nso rüstiger Kraft in des Ruders Schwung\nrühmt sich nur der, der den Wurm erschlug.\nSiegfried ist es, sicher kein andrer!","translation":"A leisurely blow,\nas if by idly hand,\nHe drives the boat against the current;\nsuch vigorous power in the oar's swing\nOnly he who slew the worm can boast.\nIt's Siegfried, certainly no one else!","literalText":true,"sourceStartIndex":108,"sourceLineCount":6},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Jagt er vorbei?","translation":"Is he speeding past?","literalText":true,"sourceStartIndex":114,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"durch die hohlen Hände nach dem Flusse rufend","translation":"calling for the river through cupped hands","literalText":true,"sourceStartIndex":115,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hoiho! Wohin,\ndu heitrer Held?","translation":"Hoiho! Where to,\nYou cheerful hero?","literalText":true,"sourceStartIndex":116,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"aus der Ferne, vom Flusse her","translation":"from a distance, from the river","literalText":true,"sourceStartIndex":118,"sourceLineCount":1},{"speaker":"SIEGFRIEDS STIMME","speakerTranslation":"SIEGFRIEDS STIMME","original":"Zu Gibichs starkem Sohne.","translation":"To Gibich's strong son.","literalText":true,"sourceStartIndex":119,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Zu seiner Halle entbiet' ich dich.","translation":"I summon you to his hall.","literalText":true,"sourceStartIndex":120,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried erscheint im Kahn am Ufer","translation":"Siegfried appears in a boat on the shore.","literalText":true,"sourceStartIndex":121,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hieher! Hier lege an!","translation":"Come here! Dock here!","literalText":true,"sourceStartIndex":122,"sourceLineCount":1}]}]},{"number":3,"originalHeading":"ZWEITE SZENE","translatedHeading":"Third Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Heil! Siegfried, teurer Held!","translatedTitle":"Hail! Siegfried, dear hero!","participants":["HAGEN","SIEGFRIED","GUNTHER","GUTRUNE"],"sourceStartIndex":0,"sourceLineCount":75,"turns":[{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Heil! Siegfried, teurer Held!","translation":"Hail! Siegfried, dear hero!","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther ist zu Hagen an das Ufer getreten. Gutrune blickt vom Hochsitze aus in staunender Bewunderung auf Siegfried. Gunther will freundlichen Gruss bieten. Alle sind in gegenseitiger stummer Betrachtung gefesselt\nauf sein Ross gelehnt, bleibt ruhig am Kahne stehen","translation":"Gunther has stepped onto the shore near Hagen. Gutrune gazes at Siegfried from her high seat in awe and admiration. Gunther wants to offer a friendly greeting. All are captivated by each other's silent contemplation.\nLeaning on his horse, he remains calmly standing by the boat.","literalText":true,"sourceStartIndex":1,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Wer ist Gibichs Sohn?","translation":"Who is Gibich's son?","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Gunther, ich, den du suchst.","translation":"Gunther, I am the one you are looking for.","literalText":true,"sourceStartIndex":4,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dich hört' ich rühmen weit am Rhein:\nnun ficht mit mir, oder sei mein Freund!","translation":"I heard you praised far on the Rhine:\nNow fight me, or be my friend!","literalText":true,"sourceStartIndex":5,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Lass den Kampf!\nSei willkommen!","translation":"Stop the fight!\nWelcome!","literalText":true,"sourceStartIndex":7,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sieht sich ruhig um","translation":"looks around calmly","literalText":true,"sourceStartIndex":9,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Wo berg' ich mein Ross?","translation":"Where can I hide my horse?","literalText":true,"sourceStartIndex":10,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ich biet' ihm Rast.","translation":"I offer him rest.","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu Hagen gewendet","translation":"turned towards Hagen","literalText":true,"sourceStartIndex":12,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Du riefst mich Siegfried:\nsahst du mich schon?","translation":"You called me Siegfried:\nHave you seen me yet?","literalText":true,"sourceStartIndex":13,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ich kannte dich nur an deiner Kraft.","translation":"I only knew you by your strength.","literalText":true,"sourceStartIndex":15,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"indem er an Hagen das Ross übergibt","translation":"by handing the horse over to Hagen","literalText":true,"sourceStartIndex":16,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Wohl hüte mir Grane! Du hieltest nie\nvon edlerer Zucht am Zaume ein Ross.","translation":"Well guard me, Grane! You never held back\nA horse of nobler breeding, on the bridle.","literalText":true,"sourceStartIndex":17,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hagen führt das Ross rechts hinter die Halle ab. Während Siegfried ihm gedankenvoll nachblickt, entfernt sich auch Gutrune, durch einen Wink Hagens bedeutet, von Siegfried unbemerkt, nach links durch eine Tür in ihr Gemach. Gunther schreitet mit Siegfried, den er dazu einlädt, in die Halle vor","translation":"Hagen leads the horse to the right, behind the hall. While Siegfried watches him thoughtfully, Gutrune, at a nod from Hagen, also slips away unnoticed by Siegfried, through a door to her chamber on the left. Gunther then enters the hall with Siegfried, whom he invites to join him.","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Begrüsse froh, o Held,\ndie Halle meines Vaters;\nwohin du schreitest,\nwas du ersiehst,\ndas achte nun dein Eigen:\ndein ist mein Erbe, Land und Leut',\nhilf, mein Leib, meinem Eide!\nMich selbst geb' ich zum Mann.","translation":"Greet me joyfully, O hero,\nmy father's hall;\nwherever you go,\nwhat you see,\nNow this is yours to own:\nMy inheritance is yours, land and people,\nHelp, my body, to my oath!\nI will give myself up as a man.","literalText":true,"sourceStartIndex":20,"sourceLineCount":8},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Nicht Land noch Leute biete ich,\nnoch Vaters Haus und Hof:\neinzig erbt' ich den eignen Leib;\nlebend zehr' ich den auf.\nNur ein Schwert hab' ich,\nselbst geschmiedet:\nhilf, mein Schwert, meinem Eide!\nDas biet' ich mit mir zum Bund.","translation":"I offer neither land nor people,\nstill father's house and farm:\nI inherited only my own body;\nI will consume him alive.\nI only have one sword,\nself-forged:\nHelp, my sword, my oath!\nI offer that as part of my commitment.","literalText":true,"sourceStartIndex":28,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"der zurückgekommen ist und jetzt hinter Siegfried steht","translation":"who has returned and is now standing behind Siegfried","literalText":true,"sourceStartIndex":36,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Doch des Niblungenhortes\nnennt die Märe dich Herrn?","translation":"But the Nibelung hoard\nDoes the tale call you Lord?","literalText":true,"sourceStartIndex":37,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sich zu Hagen umwendend","translation":"turning towards Hagen","literalText":true,"sourceStartIndex":39,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Des Schatzes vergass ich fast:\nso schätz' ich sein müss'ges Gut!\nIn einer Höhle liess ich's liegen,\nwo ein Wurm es einst bewacht'.","translation":"I almost forgot about the treasure:\nThat's how I value his precious possession!\nI left it lying in a cave,\nwhere a worm once guarded it'.","literalText":true,"sourceStartIndex":40,"sourceLineCount":4},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Und nichts entnahmst du ihm?","translation":"And you took nothing from him?","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"auf das stählerne Netzgewirk deutend, das er im Gürtel hängen hat","translation":"pointing to the steel mesh he has hanging from his belt","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dies Gewirk, unkund seiner Kraft.","translation":"This fabric, unaware of its strength.","literalText":true,"sourceStartIndex":46,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Den Tarnhelm kenn' ich,\nder Niblungen künstliches Werk:\ner taugt, bedeckt er dein Haupt,\ndir zu tauschen jede Gestalt;\nverlangt dich's an fernsten Ort,\ner entführt flugs dich dahin.\nSonst nichts entnahmst du dem Hort?","translation":"I know the Tarnhelm,\nThe Nibelungs' artificial work:\nIt's good if it covers your head,\nto exchange any form for you;\ndoes it call you to the farthest place,\nHe'll quickly whisk you away there.\nDid you take anything else from the daycare center?","literalText":true,"sourceStartIndex":47,"sourceLineCount":7},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Einen Ring.","translation":"A ring.","literalText":true,"sourceStartIndex":54,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Den hütest du wohl?","translation":"You're probably looking after him?","literalText":true,"sourceStartIndex":55,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Den hütet ein hehres Weib.","translation":"It is guarded by a noble woman.","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"für sich","translation":"for themselves","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Brünnhild'!...","translation":"Brünnhild'!...","literalText":true,"sourceStartIndex":58,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Nicht, Siegfried, sollst du mir tauschen:\nTand gäb' ich für dein Geschmeid,\nnähmst all' mein Gut du dafür.\nOhn' Entgelt dien' ich dir gern.","translation":"Siegfried, you shall not exchange this for me:\nI'd give trinkets for your jewelry,\nYou would take all my possessions for that.\nI will gladly serve you without charge.","literalText":true,"sourceStartIndex":59,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hagen ist zu Gutrunes Türe gegangen und öffnet sie jetzt. Gutrune tritt heraus, sie trägt ein gefülltes Trinkhorn und naht damit Siegfried","translation":"Hagen has gone to Gutrune's door and is now opening it. Gutrune steps out, carrying a filled drinking horn, and approaches Siegfried.","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Willkommen, Gast, in Gibichs Haus!\nSeine Tochter reicht dir den Trank.","translation":"Welcome, guest, to Gibich's house!\nHis daughter will hand you the potion.","literalText":true,"sourceStartIndex":64,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"neigt sich ihr freundlich und ergreift das Horn; er hält es gedankenvoll vor sich hin und sagt leise","translation":"He inclines towards her kindly and takes the horn; he holds it thoughtfully before him and says softly","literalText":true,"sourceStartIndex":66,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Vergäss' ich alles, was du mir gabst,\nvon einer Lehre lass' ich doch nie:\nden ersten Trunk zu treuer Minne,\nBrünnhilde, bring' ich dir!","translation":"If I were to forget everything you gave me,\nI never let go of a lesson:\nthe first drink of faithful love,\nBrünnhilde, I'll bring you!","literalText":true,"sourceStartIndex":67,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er setzt das Trinkhorn an und trinkt in einem langen Zuge. Er reicht das Horn an Gutrune zurück, die verschämt und verwirrt ihre Augen vor ihm niederschlägt\nheftet den Blick mit schnell entbrannter Leidenschaft auf sie","translation":"He raises the drinking horn to his lips and drinks in one long draught. He hands the horn back to Gutrune, who lowers her eyes before him, ashamed and confused.\nfixes his gaze on her with rapidly ignited passion","literalText":true,"sourceStartIndex":71,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Die so mit dem Blitz den Blick du mir sengst,\nwas senkst du dein Auge vor mir?","translation":"The one who flashes me a lightning bolt,\nWhy do you lower your eyes before me?","literalText":true,"sourceStartIndex":73,"sourceLineCount":2}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ha, schönstes Weib!","translatedTitle":"Ha, most beautiful woman!","participants":["SIEGFRIED","GUNTHER","BEIDE"],"sourceStartIndex":75,"sourceLineCount":71,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gutrune schlägt errötend das Auge zu ihm auf","translation":"Gutrune opens her eyes to him, blushing.","literalText":true,"sourceStartIndex":75,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ha, schönstes Weib!\nSchliesse den Blick;\ndas Herz in der Brust\nbrennt mir sein Strahl:\nzu feurigen Strömen fühl' ich\nihn zehrend zünden mein Blut!","translation":"Ha, most beautiful woman!\nClose your gaze;\nthe heart in the chest\nHis beam burns me:\nI feel myself flowing to fiery streams.\nMy blood will ignite him, consuming him!","literalText":true,"sourceStartIndex":76,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit bebender Stimme","translation":"with a trembling voice","literalText":true,"sourceStartIndex":82,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Gunther, wie heisst deine Schwester?","translation":"Gunther, what's your sister's name?","literalText":true,"sourceStartIndex":83,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Gutrune.","translation":"Gutrune.","literalText":true,"sourceStartIndex":84,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"leise","translation":"quiet","literalText":true,"sourceStartIndex":85,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Sind's gute Runen,\ndie ihrem Aug' ich entrate?","translation":"Are they good runes?\nwhich I can do without from their eye?","literalText":true,"sourceStartIndex":86,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er fasst Gutrune mit feurigem Ungestüm bei der Hand","translation":"He seizes Gutrune by the hand with fiery impetuosity.","literalText":true,"sourceStartIndex":88,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Deinem Bruder bot ich mich zum Mann:\nder Stolze schlug mich aus;\ntrügst du, wie er, mir Übermut,\nböt' ich mich dir zum Bund?","translation":"I offered myself as a husband to your brother:\nThe proud man beat me up;\nAre you deceiving me, like he did, with arrogance?\nWould I offer myself to join your service?","literalText":true,"sourceStartIndex":89,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gutrune trifft unwillkürlich auf Hagens Blick. Sie neigt demütig das Haupt, und mit einer Gebärde, als fühle sie sich seiner nicht wert, verlässt sie schwankenden Schrittes wieder die Halle\nvon Hagen und Gunther aufmerksam beobachtet, blickt ihr, wie festgezaubert, nach; dann, ohne sich umzuwenden, fragt er:","translation":"Gutrune's gaze involuntarily meets Hagen's. She bows her head humbly, and with a gesture as if she feels unworthy of him, she leaves the hall again with unsteady steps.\nHagen and Gunther watched her attentively, and he gazed after her as if spellbound; then, without turning around, he asked:","literalText":true,"sourceStartIndex":93,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hast du, Gunther, ein Weib?","translation":"Do you, Gunther, have a wife?","literalText":true,"sourceStartIndex":95,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Nicht freit' ich noch,\nund einer Frau soll ich mich schwerlich freun!\nAuf eine setzt' ich den Sinn,\ndie kein Rat mir je gewinnt.","translation":"I was not yet married,\nAnd I should hardly be happy with a woman!\nI placed my hopes on one,\nwhich no advice will ever win me.","literalText":true,"sourceStartIndex":96,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wendet sich lebhaft zu Gunther","translation":"turns animatedly to Gunther","literalText":true,"sourceStartIndex":100,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Was wär' dir versagt, steh' ich zu dir?","translation":"What would you be denied if I stood by you?","literalText":true,"sourceStartIndex":101,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Auf Felsen hoch ihr Sitz -","translation":"Their seat high on the rocks -","literalText":true,"sourceStartIndex":102,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit verwunderungsvoller Hast einfallend","translation":"intruding with astonishing haste","literalText":true,"sourceStartIndex":103,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"\"Auf Felsen hoch ihr Sitz;\"","translation":"\"On the rocks high their seat;\"","literalText":true,"sourceStartIndex":104,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"ein Feuer umbrennt den Saal -","translation":"A fire surrounds the hall -","literalText":true,"sourceStartIndex":105,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"\"ein Feuer umbrennt den Saal\"... ?","translation":"\"A fire engulfs the hall\"...?","literalText":true,"sourceStartIndex":106,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Nur wer durch das Feuer bricht -","translation":"Only those who break through the fire -","literalText":true,"sourceStartIndex":107,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit der heftigsten Anstrengung, um eine Erinnerung festzuhalten","translation":"with the most intense effort to capture a memory","literalText":true,"sourceStartIndex":108,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"\"Nur wer durch das Feuer bricht\"... ?","translation":"\"Only those who break through the fire\"...?","literalText":true,"sourceStartIndex":109,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"- darf Brünnhildes Freier sein.","translation":"- may be Brünnhilde's suitor.","literalText":true,"sourceStartIndex":110,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried drückt durch eine Gebärde aus, dass bei Nennung von Brünnhildes Namen die Erinnerung ihm vollends ganz schwindet","translation":"Siegfried expresses through a gesture that when Brünnhilde's name is mentioned, his memory completely fades.","literalText":true,"sourceStartIndex":111,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Nun darf ich den Fels nicht erklimmen;\ndas Feuer verglimmt mir nie!","translation":"Now I am not allowed to climb the rock;\nMy fire will never die down!","literalText":true,"sourceStartIndex":112,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"kommt aus einem traumartigen Zustand zu sich und wendet sich mit übermütiger Lustigkeit zu Gunther","translation":"He comes to from a dreamlike state and turns to Gunther with exuberant merriment.","literalText":true,"sourceStartIndex":114,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ich - fürchte kein Feuer,\nfür dich frei ich die Frau;\ndenn dein Mann bin ich,\nund mein Mut ist dein,\ngewinn' ich mir Gutrun' zum Weib.","translation":"I fear no fire,\nI, the woman, am free for you;\nbecause I am your husband\nand my courage is yours,\nI will win Gutrun as my wife.","literalText":true,"sourceStartIndex":115,"sourceLineCount":5},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Gutrune gönn' ich dir gerne.","translation":"I'm happy to give you Gutrune.","literalText":true,"sourceStartIndex":120,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Brünnhilde bring' ich dir.","translation":"I'll bring Brünnhilde to you.","literalText":true,"sourceStartIndex":121,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Wie willst du sie täuschen?","translation":"How do you intend to deceive her?","literalText":true,"sourceStartIndex":122,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Durch des Tarnhelms Trug\ntausch' ich mir deine Gestalt.","translation":"Through the illusion of the Tarnhelm\nI'll exchange your form for mine.","literalText":true,"sourceStartIndex":123,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"So stelle Eide zum Schwur!","translation":"So make oaths a vow!","literalText":true,"sourceStartIndex":125,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Blut-Brüderschaft schwöre ein Eid!","translation":"Blood brotherhood, swear an oath!","literalText":true,"sourceStartIndex":126,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hagen füllt ein Trinkhorn mit frischem Wein; dieses hält er dann Siegfried und Gunther hin, welche sich mit ihren Schwertern die Arme ritzen und diese eine kurze Zeit über die Öffnung des Trinkhornes halten. Siegfried und Gunther legen zwei ihrer Finger auf das Horn, welches Hagen fortwährend in ihrer Mitte hält.","translation":"Hagen fills a drinking horn with fresh wine; he then holds it out to Siegfried and Gunther, who cut their arms with their swords and hold them briefly over the opening of the horn. Siegfried and Gunther place two of their fingers on the horn, which Hagen continues to hold between them.","literalText":true,"sourceStartIndex":127,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Blühenden Lebens labendes Blut\nträufelt' ich in den Trank.","translation":"The life-giving blood of blossoming life\nI dripped it into the drink.","literalText":true,"sourceStartIndex":128,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Bruder-brünstig mutig gemischt,\nblüh' im Trank unser Blut.","translation":"Brotherly-lustful, bravely mixed,\nMay our blood bloom in the drink.","literalText":true,"sourceStartIndex":130,"sourceLineCount":2},{"speaker":"BEIDE","speakerTranslation":"BEIDE","original":"Treue trink' ich dem Freund.\nFroh und frei entblühe dem Bund,\nBlut-Brüderschaft heut'!","translation":"I drink to my friend's loyalty.\nJoyfully and freely blossom from the union,\nBlood brotherhood today!","literalText":true,"sourceStartIndex":132,"sourceLineCount":3},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Bricht ein Bruder den Bund,","translation":"If one brother breaks the covenant,","literalText":true,"sourceStartIndex":135,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Trügt den Treuen der Freund,","translation":"If a friend deceives the faithful,","literalText":true,"sourceStartIndex":136,"sourceLineCount":1},{"speaker":"BEIDE","speakerTranslation":"BEIDE","original":"Was in Tropfen heut' hold wir tranken,\nin Strahlen ström' es dahin,\nfromme Sühne dem Freund!","translation":"What we drank today in drops,\nIt flowed away in rays,\nPious atonement for the friend!","literalText":true,"sourceStartIndex":137,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"trinkt und reicht das Horn Siegfried","translation":"drinks and hands over the horn Siegfried","literalText":true,"sourceStartIndex":140,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"So - biet' ich den Bund.","translation":"So - I offer the alliance.","literalText":true,"sourceStartIndex":141,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So - trink' ich dir Treu'!","translation":"So - I drink to your loyalty!","literalText":true,"sourceStartIndex":142,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er trinkt und hält das geleerte Trinkhorn Hagen hin. Hagen zerschlägt mit seinem Schwerte das Horn in zwei Stücke. Siegfried und Gunther reichen sich die Hände\nbetrachtet Hagen, welcher während des Schwures hinter ihm gestanden","translation":"He drinks and holds out the empty drinking horn to Hagen. Hagen smashes the horn in two with his sword. Siegfried and Gunther shake hands.\nHagen, who had stood behind him during the oath, was observed.","literalText":true,"sourceStartIndex":143,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Was nahmst du am Eide nicht teil?","translation":"Why did you not participate in the oath?","literalText":true,"sourceStartIndex":145,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Mein Blut verdürb' euch den Trank;","translatedTitle":"May my blood spoil your drink;","participants":["HAGEN","GUNTHER","SIEGFRIED","GUTRUNE"],"sourceStartIndex":146,"sourceLineCount":42,"turns":[{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Mein Blut verdürb' euch den Trank;\nnicht fliesst mir's echt und edel wie euch;\nstörrisch und kalt stockt's in mir;\nnicht will's die Wange mir röten.\nDrum bleibt ich fern vom feurigen Bund.","translation":"May my blood spoil your drink;\nIt doesn't flow to me as genuinely and noblely as it does to you;\nStubborn and cold, it stagnates within me;\nIt doesn't want to make my cheek red.\nTherefore, I stay away from the fiery alliance.","literalText":true,"sourceStartIndex":146,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu Siegfried","translation":"to Siegfried","literalText":true,"sourceStartIndex":151,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Lass den unfrohen Mann!","translation":"Leave the unhappy man alone!","literalText":true,"sourceStartIndex":152,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"hängt sich den Schild wieder über","translation":"hangs the sign back over","literalText":true,"sourceStartIndex":153,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Frisch auf die Fahrt!\nDort liegt mein Schiff;\nschnell führt es zum Felsen.","translation":"Let's get going!\nMy ship is there;\nIt quickly leads to the rock.","literalText":true,"sourceStartIndex":154,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er tritt näher zu Gunther und bedeutet diesen","translation":"He steps closer to Gunther and gestures to him","literalText":true,"sourceStartIndex":157,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Eine Nacht am Ufer harrst du im Nachen;\ndie Frau fährst du dann heim.","translation":"You waited one night on the shore in the boat;\nThen you drive the woman home.","literalText":true,"sourceStartIndex":158,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er wendet sich zum Fortgehen und winkt Gunther, ihm zu folgen","translation":"He turns to leave and beckons Gunther to follow him.","literalText":true,"sourceStartIndex":160,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Rastest du nicht zuvor?","translation":"Didn't you rest beforehand?","literalText":true,"sourceStartIndex":161,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Um die Rückkehr ist mir's jach!","translation":"I'm really looking forward to returning!","literalText":true,"sourceStartIndex":162,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er geht zum Ufer, um das Schiff loszubinden","translation":"He goes to the shore to untie the ship.","literalText":true,"sourceStartIndex":163,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Du, Hagen, bewache die Halle!","translation":"You, Hagen, guard the hall!","literalText":true,"sourceStartIndex":164,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er folgt Siegfried zum Ufer. - Während Siegfried und Gunther, nachdem sie ihre Waffen darin niedergelegt, im Schiff das Segel aufstecken und alles zur Abfahrt bereit machen, nimmt Hagen seinen Speer und Schild. Gutrune erscheint an der Tür ihres Gemachs, als soeben Siegfried das Schiff abstösst, welches sogleich der Mitte des Stromes zutreibt.","translation":"He follows Siegfried to the shore. While Siegfried and Gunther, having laid down their weapons, hoist the sail in the ship and prepare everything for departure, Hagen takes his spear and shield. Gutrune appears at the door of her chamber just as Siegfried pushes off with the ship, which immediately drifts towards the middle of the river.","literalText":true,"sourceStartIndex":165,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Wohin eilen die Schnellen?","translation":"Where are the fast ones rushing to?","literalText":true,"sourceStartIndex":166,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"während er sich gemächlich mit Schild und Speer vor der Halle niedersetzt","translation":"while he leisurely sits down in front of the hall with his shield and spear","literalText":true,"sourceStartIndex":167,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Zu Schiff - Brünnhild' zu frein.","translation":"To ship - Brünnhild' to court.","literalText":true,"sourceStartIndex":168,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Siegfried?","translation":"Siegfried?","literalText":true,"sourceStartIndex":169,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Sieh', wie's ihn treibt,\nzum Weib dich zu gewinnen!","translation":"Look how he's driven,\nTo win you as a woman!","literalText":true,"sourceStartIndex":170,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Siegfried - mein!","translation":"Siegfried - mine!","literalText":true,"sourceStartIndex":172,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie geht, lebhaft erregt, in ihr Gemach zurück. Siegfried hat das Ruder erfasst und treibt jetzt mit dessen Schlägen den Nachen stromabwärts, so dass dieser bald gänzlich ausser Gesicht kommt\nsitzt mit dem Rücken an den Pfosten der Halle gelehnt, bewegungslos","translation":"She returns to her chamber, agitated. Siegfried has seized the oar and is now propelling the boat downstream with its strokes, so that it soon disappears completely from sight.\nsits with his back against the hall's post, motionless","literalText":true,"sourceStartIndex":173,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hier sitz' ich zur Wacht, wahre den Hof,\nwehre die Halle dem Feind.\nGibichs Sohne wehet der Wind,\nauf Werben fährt er dahin.\nlhm führt das Steuer ein starker Held,\nGefahr ihm will er bestehn:\nDie eigne Braut ihm bringt er zum Rhein;\nmir aber bringt er - den Ring!\nIhr freien Söhne, frohe Gesellen,\nsegelt nur lustig dahin!\nDünkt er euch niedrig, ihr dient ihm doch,\ndes Niblungen Sohn.","translation":"Here I sit on guard, watching over the courtyard,\nDefend the hall against the enemy.\nThe wind blows for Gibich's sons,\nHe drives there via Werben.\nLhm is at the helm, a strong hero,\nHe wants to withstand the danger:\nHe brings his own bride to the Rhine;\nBut for me, he brings - the ring!\nYou free sons, merry companions,\nJust sail along merrily!\nThough you may think him lowly, you still serve him.\nson of the Nibelung.","literalText":true,"sourceStartIndex":175,"sourceLineCount":12},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ein Teppich, welcher dem Vordergrunde zu die Halle einfasste, schlägt zusammen und schliesst die Bühne vor dem Zuschauer ab. Nachdem während eines kurzen Orchester-Zwischenspieles der Schauplatz verwandelt ist, wird der Teppich gänzlich aufgezogen","translation":"A carpet, which framed the hall towards the foreground, folds up, closing off the stage in front of the audience. After a brief orchestral interlude transforming the scene, the carpet is fully retracted.","literalText":true,"sourceStartIndex":187,"sourceLineCount":1}]}]},{"number":4,"originalHeading":"DRITTE SZENE","translatedHeading":"Fourth Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Altgewohntes Geräusch","translatedTitle":"familiar sound","participants":["BRÜNNHILDE","WALTRAUTES STIMME","WALTRAUTE"],"sourceStartIndex":0,"sourceLineCount":68,"turns":[{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Altgewohntes Geräusch\nraunt meinem Ohr die Ferne.\nEin Luftross jagt im Laufe daher;\nauf der Wolke fährt es wetternd zum Fels.\nWer fand mich Einsame auf?","translation":"familiar sound\nThe distance whispers to my ear.\nAn air horse races along;\nIt travels on the cloud, ranting and raving, towards the rock.\nWho found me, a lonely person?","literalText":true,"sourceStartIndex":0,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"aus der Ferne","translation":"from a distance","literalText":true,"sourceStartIndex":5,"sourceLineCount":1},{"speaker":"WALTRAUTES STIMME","speakerTranslation":"WALTRAUTES STIMME","original":"Brünnhilde! Schwester!\nSchläfst oder wachst du?","translation":"Brünnhilde! Sister!\nAre you asleep or awake?","literalText":true,"sourceStartIndex":6,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"fährt vom Sitze auf","translation":"moves from the seat to","literalText":true,"sourceStartIndex":8,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Waltrautes Ruf, so wonnig mir kund!","translation":"Waltraute's call, so blissfully known to me!","literalText":true,"sourceStartIndex":9,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in die Szene rufend","translation":"calling out into the scene","literalText":true,"sourceStartIndex":10,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Kommst du, Schwester?\nSchwingst dich kühn zu mir her?","translation":"Are you coming, sister?\nAre you boldly swinging towards me?","literalText":true,"sourceStartIndex":11,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sie eilt nach dem Felsrande","translation":"She hurries towards the edge of the cliff.","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Dort im Tann\n- dir noch vertraut -\nsteige vom Ross\nund stell' den Renner zur Rast!","translation":"There in the woods\n- still familiar to you -\ndismount from your horse\nand park the racer for a rest!","literalText":true,"sourceStartIndex":14,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie stürmt in den Tann, von wo ein starkes Geräusch, gleich einem Gewitterschlage, sich vernehmen lässt. Dann kommt sie in heftiger Bewegung mit Waltraute zurück; sie bleibt freudig erregt, ohne Waltrautes ängstliche Scheu zu beachten","translation":"She rushes into the fir forest, from where a loud noise, like a thunderclap, can be heard. Then she comes back in a flurry of activity with Waltraute; she remains joyfully excited, oblivious to Waltraute's fearful shyness.","literalText":true,"sourceStartIndex":18,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Kommst du zu mir?\nBist du so kühn,\nmagst ohne Grauen\nBrünnhild' bieten den Gruss?","translation":"Will you come to me?\nAre you so bold,\nYou like it without horror\nBrünnhilde offer their greetings?","literalText":true,"sourceStartIndex":19,"sourceLineCount":4},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Einzig dir nur galt meine Eil'!","translation":"My haste was directed solely towards you!","literalText":true,"sourceStartIndex":23,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in höchster freudiger Aufgeregtheit","translation":"in the highest joyful excitement","literalText":true,"sourceStartIndex":24,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"So wagtest du, Brünnhild' zulieb,\nWalvaters Bann zu brechen?\nOder wie - o sag' -\nwär' wider mich Wotans Sinn erweicht?\nAls dem Gott entgegen Siegmund ich schützte,\nfehlend - ich weiss es -\nerfüllt' ich doch seinen Wunsch.\nDass sein Zorn sich verzogen,\nweiss ich auch;\ndenn verschloss er mich gleich in Schlaf,\nfesselt' er mich auf den Fels,\nwies er dem Mann mich zur Magd,\nder am Weg mich fänd' und erweckt',\nmeiner bangen Bitte doch gab er Gunst:\nmit zehrendem Feuer umzog er den Fels,\ndem Zagen zu wehren den Weg.\nSo zur Seligsten schuf mich die Strafe:\nder herrlichste Held\ngewann mich zum Weib!\nIn seiner Liebe leucht' und lach' ich heut' auf.","translation":"So you dared, for Brünnhild's sake,\nTo break the Walvater's curse?\nOr how - oh tell me -\nwould Wotan's mind have softened against me?\nWhen I protected Siegmund against the god,\nMissing - I know it -\nI did fulfill his wish.\nThat his anger subsided,\nI know that too;\nfor he immediately locked me in sleep\nHe bound me to the rock,\nHe assigned me to be a maid to the man,\nwho would find me on the way and awaken me,\nHe granted my anxious request:\nHe surrounded the rock with consuming fire,\nto resist hesitancy.\nThus punishment created me to be the Blessed One:\nthe most glorious hero\nI won her over!\nIn his love I shine and laugh today.","literalText":true,"sourceStartIndex":25,"sourceLineCount":20},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie umarmt Waltraute unter stürmischen Freudenbezeigungen, welche diese mit scheuer Ungeduld abzuwehren sucht","translation":"She embraces Waltraute with boisterous displays of joy, which Waltraute tries to fend off with timid impatience.","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Lockte dich, Schwester, mein Los?\nAn meiner Wonne willst du dich weiden,\nteilen, was mich betraf?","translation":"Did my fate entice you, sister?\nYou will feast on my delight,\nshare what concerned me?","literalText":true,"sourceStartIndex":46,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heftig","translation":"violent","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Teilen den Taumel, der dich Törin erfasst?\nEin andres bewog mich in Angst,\nzu brechen Wotans Gebot.","translation":"Do you share the euphoria that grips you, fool?\nAnother thing filled me with fear,\nto break Wotan's commandment.","literalText":true,"sourceStartIndex":50,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Brünnhilde gewahrt hier erst mit Befremdung die wildaufgeregte Stimmung Waltrautes","translation":"Brünnhilde initially notices Waltraute's wildly excited mood with some bewilderment.","literalText":true,"sourceStartIndex":53,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Angst und Furcht fesseln dich Arme?\nSo verzieh der Strenge noch nicht?\nDu zagst vor des Strafenden Zorn?","translation":"Are fear and dread holding you captive?\nSo the severity hasn't been forgiven yet?\nAre you afraid of the wrath of the punisher?","literalText":true,"sourceStartIndex":54,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"düster","translation":"grim","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Dürft' ich ihn fürchten,\nmeiner Angst fänd' ich ein End'!","translation":"May I fear him?\nMy fear would finally come to an end!","literalText":true,"sourceStartIndex":58,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Staunend versteh' ich dich nicht!","translation":"I'm amazed and don't understand you!","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Wehre der Wallung:\nachtsam höre mich an!\nNach Walhall wieder\ndrängt mich die Angst,\ndie von Walhall hierher mich trieb.","translation":"Dams of the surge:\nListen to me attentively!\nBack to Valhall\nI am overcome by fear,\nwhich drove me here from Valhalla.","literalText":true,"sourceStartIndex":61,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"erschrocken","translation":"frightened","literalText":true,"sourceStartIndex":66,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Was ist's mit den ewigen Göttern?","translation":"What about the eternal gods?","literalText":true,"sourceStartIndex":67,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Höre mit Sinn, was ich dir sage!","translatedTitle":"Listen carefully to what I tell you!","participants":["WALTRAUTE","BRÜNNHILDE"],"sourceStartIndex":68,"sourceLineCount":73,"turns":[{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Höre mit Sinn, was ich dir sage!\nSeit er von dir geschieden,\nzur Schlacht nicht mehr schickte uns Wotan;\nirr und ratlos ritten wir ängstlich zu Heer;\nWalhalls mutige Helden mied Walvater.\nEinsam zu Ross, ohne Ruh' noch Rast,\ndurchschweift er als Wandrer die Welt.\nJüngst kehrte er heim;\nin der Hand hielt er seines Speeres Splitter:\ndie hatte ein Held ihm geschlagen.\nMit stummem Wink Walhalls Edle\nwies er zum Forst, die Weltesche zu fällen.\nDes Stammes Scheite hiess er sie schichten\nzu ragendem Hauf rings um der Seligen Saal.\nDer Götter Rat liess er berufen;\nden Hochsitz nahm heilig er ein:\nihm zu Seiten hiess er die Bangen sich setzen,\nin Ring und Reih' die Hall' erfüllen die Helden.\nSo sitzt er, sagt kein Wort,\nauf hehrem Sitze stumm und ernst,\ndes Speeres Splitter fest in der Faust;\nHoldas Äpfel rührt er nicht an.\nStaunen und Bangen binden starr die Götter.\nSeine Raben beide sandt' er auf Reise:\nkehrten die einst mit guter Kunde zurück,\ndann noch einmal - zum letztenmal -\nlächelte ewig der Gott.\nSeine Knie umwindend, liegen wir Walküren;\nblind bleibt er den flehenden Blicken;\nuns alle verzehrt Zagen und endlose Angst.\nAn seine Brust presst' ich mich weinend:\nda brach sich sein Blick -\ner gedachte, Brünnhilde, dein'!\nTief seufzt' er auf, schloss das Auge,\nund wie im Traume\nraunt' er das Wort:\n\"Des tiefen Rheines Töchtern\ngäbe den Ring sie wieder zurück,\nvon des Fluches Last\nerlöst wär' Gott und Welt!\"\nDa sann ich nach: von seiner Seite\ndurch stumme Reihen stahl ich mich fort;\nin heimlicher Hast bestieg ich mein Ross\nund ritt im Sturme zu dir.\nDich, o Schwester, beschwör' ich nun:\nwas du vermagst, vollend' es dein Mut!\nEnde der Ewigen Qual!","translation":"Listen carefully to what I tell you!\nSince he divorced you,\nWotan no longer sent us to battle;\nLost and perplexed, we rode fearfully to the army;\nValhalla's brave heroes were avoided by the Allfather.\nAlone on horseback, without rest or respite,\nHe roams the world as a wanderer.\nHe recently returned home;\nIn his hand he held splinters of his spear:\nA hero had beaten him.\nWith a silent nod, Valhalla's nobles\nHe directed them to the forestry service to fell the World Ash tree.\nHe told them to stack the logs of the tree.\na towering crowd surrounding the Blessed Hall.\nHe summoned the council of the gods;\nHe took the high seat in a holy manner:\nHe told the anxious ones to sit down beside him.\nIn ring and row the hall the heroes fill.\nHe sits there, saying nothing.\nsilent and solemn in his lofty seat,\nsplinter of the spear firmly in his fist;\nHe doesn't touch Holda's apples.\nWonder and fear bind the gods rigidly.\nHe sent both his ravens on a journey:\nThey once returned with good news,\nthen once more - for the last time -\nThe god smiled eternally.\nWrapping around his knees, we Valkyries lie;\nHe remains blind to the pleading glances;\nWe are all consumed by timidity and endless fear.\nI pressed myself against his chest, crying:\nthen his gaze broke -\nHe thought of you, Brünnhilde!\nHe sighed deeply and closed his eye.\nand as if in a dream\nHe whispered the word:\n\"Daughters of the deep Rhine\nShe would give the ring back.\nof the curse's burden\nGod and the world would be redeemed!\nThen I pondered: from his side\nI stole away through silent rows;\nIn secret haste I mounted my horse\nand rode to you in the storm.\nYou, O sister, I now implore:\nWhatever you are capable of, your courage will accomplish it!\nThe End of Eternal Torment!","literalText":true,"sourceStartIndex":68,"sourceLineCount":47},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie hat sich vor Brünnhilde niedergeworfen\nruhig","translation":"She threw herself down before Brünnhilde.\nquiet","literalText":true,"sourceStartIndex":115,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Welch' banger Träume Mären\nmeldest du Traurige mir!\nDer Götter heiligem Himmelsnebel\nbin ich Törin enttaucht:\nnicht fass ich, was ich erfahre.\nWirr und wüst scheint mir dein Sinn;\nin deinem Aug' - so übermüde -\nglänzt flackernde Glut.\nMit blasser Wange, du bleiche Schwester,\nwas willst du Wilde von mir?","translation":"What anxious dreams and tales\nPlease report any sad people to me!\nThe gods' sacred celestial mist\nI, a fool, have dived:\nI can't believe what I'm learning.\nYour mind seems confused and desolate to me;\nin your eye - so tired -\nA flickering glow of embers shines.\nWith pale cheeks, you pale sister,\nWhat do you want from me, you savage?","literalText":true,"sourceStartIndex":117,"sourceLineCount":10},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heftig","translation":"violent","literalText":true,"sourceStartIndex":127,"sourceLineCount":1},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"An deiner Hand, der Ring,\ner ist's; - hör' meinen Rat:\nfür Wotan wirf ihn von dir!","translation":"On your hand, the ring,\nIt's him; - listen to my advice:\nFor Wotan, throw him away from you!","literalText":true,"sourceStartIndex":128,"sourceLineCount":3},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Den Ring? - Von mir?","translation":"The ring? - From me?","literalText":true,"sourceStartIndex":131,"sourceLineCount":1},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Den Rheintöchtern gib ihn zurück!","translation":"Give it back to the Rhine maidens!","literalText":true,"sourceStartIndex":132,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Den Rheintöchtern - ich - den Ring?\nSiegfrieds Liebespfand?\nBist du von Sinnen?","translation":"To the Rhine maidens - me - the ring?\nSiegfried's love token?\nAre you out of your mind?","literalText":true,"sourceStartIndex":133,"sourceLineCount":3},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Hör' mich! Hör' meine Angst!\nDer Welt Unheil haftet sicher an ihm.\nWirf ihn von dir, fort in die Welle!\nWalhalls Elend zu enden,\nden verfluchten wirf in die Flut!","translation":"Listen to me! Hear my fear!\nThe world's misfortunes are surely attached to him.\nThrow him away from you, into the wave!\nTo end Valhalla's misery,\nThrow the cursed one into the flood!","literalText":true,"sourceStartIndex":136,"sourceLineCount":5}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ha! Weisst du, was er mir ist?","translatedTitle":"Ha! Do you know what he is to me?","participants":["BRÜNNHILDE","WALTRAUTE","SIEGFRIED"],"sourceStartIndex":141,"sourceLineCount":75,"turns":[{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Ha! Weisst du, was er mir ist?\nWie kannst du's fassen, fühllose Maid!\nMehr als Walhalls Wonne,\nmehr als der Ewigen Ruhm\nist mir der Ring:\nein Blick auf sein helles Gold,\nein Blitz aus dem hehren Glanz\ngilt mir werter\nals aller Götter ewig währendes Glück!\nDenn selig aus ihm leuchtet mir Siegfrieds Liebe:\nSiegfrieds Liebe!\nO liess' sich die Wonne dir sagen!\nSie - wahrt mir der Reif.\nGeh' hin zu der Götter heiligem Rat!\nVon meinem Ringe raune ihnen zu:\ndie Liebe liesse ich nie,\nmir nähmen nie sie die Liebe,\nstürzt' auch in Trümmern\nWalhalls strahlende Pracht!","translation":"Ha! Do you know what he is to me?\nHow can you believe it, you heartless maid!\nMore than Valhalla's delight,\nmore than eternal glory\nIs the ring to me:\na glimpse of its bright gold,\na flash from the sublime splendor\nThis applies to me, dear [name].\nas the eternal happiness of all gods!\nFor blessed from him shines Siegfried's love for me:\nSiegfried's love!\nOh, how wonderful it was to tell you!\nShe - preserves my frost.\nGo to the holy council of the gods!\nFrom my ring I whisper to them:\nI would never let go of love,\nThey would never take away my love,\nalso falls into ruins\nValhalla's radiant splendor!","literalText":true,"sourceStartIndex":141,"sourceLineCount":19},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Dies deine Treue?\nSo in Trauer\nentlässest du lieblos die Schwester?","translation":"Is this your loyalty?\nSo in mourning\nAre you letting your sister go without love?","literalText":true,"sourceStartIndex":160,"sourceLineCount":3},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Schwinge dich fort!\nFliege zu Ross!\nDen Ring entführst du mir nicht!","translation":"Swing away!\nFly on horseback!\nYou won't steal my ring!","literalText":true,"sourceStartIndex":163,"sourceLineCount":3},{"speaker":"WALTRAUTE","speakerTranslation":"WALTRAUTE","original":"Wehe! Wehe!\nWeh' dir, Schwester!\nWalhalls Göttern weh'!","translation":"Woe is me! Woe is me!\nWoe to you, sister!\nWoe to the gods of Valhalla!","literalText":true,"sourceStartIndex":166,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie stürzt fort. Bald erhebt sich unter Sturm eine Gewitterwolke aus dem Tann\nwährend sie der davonjagenden, hell erleuchteten Gewitterwolke, die sich bald gänzlich in der Ferne verliert, nachblickt","translation":"She rushes off. Soon, a storm cloud rises from the fir trees amidst the wind.\nas she watches the brightly lit storm cloud speeding away, soon disappearing completely into the distance.","literalText":true,"sourceStartIndex":169,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Blitzend Gewölk,\nvom Wind getragen,\nstürme dahin:\nzu mir nie steure mehr her!","translation":"Flashing clouds,\ncarried by the wind\nstorms there:\nNever come here again!","literalText":true,"sourceStartIndex":171,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Es ist Abend geworden. Aus der Tiefe leuchtet der Feuerschein allmählich heller auf. Brünnhilde blickt ruhig in die Landschaft hinaus","translation":"Evening has fallen. From the depths, the firelight gradually shines brighter. Brünnhilde gazes calmly out at the landscape.","literalText":true,"sourceStartIndex":175,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Abendlich Dämmern deckt den Himmel;\nheller leuchtet die hütende Lohe herauf.","translation":"Evening twilight covers the sky;\nThe protective flame shines brighter.","literalText":true,"sourceStartIndex":176,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Der Feuerschein nähert sich aus der Tiefe. Immer glühendere Flammenzungen lecken über den Felsensaum auf","translation":"The glow of the fire approaches from the depths. Ever more intense tongues of flame lick up over the edge of the rocks.","literalText":true,"sourceStartIndex":178,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Was leckt so wütend\ndie lodernde Welle zum Wall?\nZur Felsenspitze wälzt sich der feurige Schwall.","translation":"What's licking so angrily?\nThe blazing wave to the wall?\nThe fiery torrent rolls towards the rocky summit.","literalText":true,"sourceStartIndex":179,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Man hört aus der Tiefe Siegfrieds Hornruf nahen. Brünnhilde lauscht und fährt entzückt auf","translation":"From the depths, Siegfried's horn call is heard approaching. Brünnhilde listens and starts up in delight.","literalText":true,"sourceStartIndex":182,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Siegfried! Siegfried zurück?\nSeinen Ruf sendet er her!\nAuf! - Auf! Ihm entgegen!\nIn meines Gottes Arm!","translation":"Siegfried! Siegfried back?\nHe sends his call here!\nUp! - Up! Towards him!\nIn the arms of my God!","literalText":true,"sourceStartIndex":183,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie eilt in höchstem Entzücken dem Felsrande zu. Feuerflammen schlagen herauf: aus ihnen springt Siegfried auf einen hochragenden Felsstein empor, worauf die Flammen sogleich wieder zurückweichen und abermals nur aus der Tiefe heraufleuchten. Siegfried, auf dem Haupte den Tarnhelm, der ihm bis zur Hälfte das Gesicht verdeckt und nur die Augen freilässt, erscheint in Gunthers Gestalt\nvoll Entsetzen zurückweichend","translation":"She rushes to the edge of the cliff in rapture. Flames leap up: from them Siegfried leaps onto a towering rock, whereupon the flames immediately recede and once more only gleam from the depths below. Siegfried, wearing the Tarnhelm, which covers half his face and leaves only his eyes visible, appears in Gunther's form.\nrecoiling in utter horror","literalText":true,"sourceStartIndex":187,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Verrat! Wer drang zu mir?","translation":"Betrayal! Who came to me?","literalText":true,"sourceStartIndex":189,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie flieht bis in den Vordergrund und heftet von da aus in sprachlosem Erstaunen ihren Blick auf Siegfried\nim Hintergrunde auf dem Steine verweilend, betrachtet sie lange, regungslos auf seinen Schild gelehnt; dann redet er sie mit verstellter - tieferer - Stimme an","translation":"She flees to the foreground and from there fixes her gaze on Siegfried in speechless astonishment.\nLingering in the background on the stone, he gazes at her for a long time, leaning motionless against his shield; then he addresses her in a disguised - deeper - voice.","literalText":true,"sourceStartIndex":190,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Brünnhild'! Ein Freier kam,\nden dein Feuer nicht geschreckt.\nDich werb' ich nun zum Weib:\ndu folge willig mir!","translation":"Brünnhild'! A suitor came,\nwhom your fire did not frighten.\nI now woo you as my wife:\nYou will follow me willingly!","literalText":true,"sourceStartIndex":192,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heftig zitternd","translation":"violently trembling","literalText":true,"sourceStartIndex":196,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Wer ist der Mann,\nder das vermochte,\nwas dem Stärksten nur bestimmt?","translation":"Who is this man?\nwho was able to do that,\nWhat is only destined for the strongest?","literalText":true,"sourceStartIndex":197,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"unverändert wie zuvor","translation":"unchanged as before","literalText":true,"sourceStartIndex":200,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ein Helde, der dich zähmt,\nbezwingt Gewalt dich nur.","translation":"A hero who tames you,\nViolence will only defeat you.","literalText":true,"sourceStartIndex":201,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"von Grausen erfasst","translation":"seized by horror","literalText":true,"sourceStartIndex":203,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Ein Unhold schwang sich auf jenen Stein!\nEin Aar kam geflogen,\nmich zu zerfleischen!\nWer bist du, Schrecklicher?","translation":"A monster climbed onto that stone!\nAn eagle came flying,\nto tear me to pieces!\nWho are you, Terrible One?","literalText":true,"sourceStartIndex":204,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"langes Schweigen","translation":"long silence","literalText":true,"sourceStartIndex":208,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Stammst du von Menschen?\nKommst du von Hellas nächtlichem Heer?","translation":"Are you descended from humans?\nDo you come from Hellas' night army?","literalText":true,"sourceStartIndex":209,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wie zuvor, mit etwas bebender Stimme beginnend, alsbald aber wieder sicherer fortfahrend","translation":"as before, beginning with a slightly trembling voice, but soon continuing more confidently.","literalText":true,"sourceStartIndex":211,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ein Gibichung bin ich,\nund Gunther heisst der Held,\ndem, Frau, du folgen sollst.","translation":"I am a Gibichung,\nand Gunther is the name of the hero,\nwhom, woman, you should follow.","literalText":true,"sourceStartIndex":212,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in Verzweiflung ausbrechend","translation":"breaking out in despair","literalText":true,"sourceStartIndex":215,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Wotan! Ergrimmter, grausamer Gott!","translatedTitle":"Wotan! Wrathful, cruel god!","participants":["BRÜNNHILDE","SIEGFRIED"],"sourceStartIndex":216,"sourceLineCount":35,"turns":[{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Wotan! Ergrimmter, grausamer Gott!\nWeh'! Nun erseh' ich der Strafe Sinn:\nzu Hohn und Jammer jagst du mich hin!","translation":"Wotan! Wrathful, cruel god!\nWoe! Now I understand the meaning of the punishment:\nYou drive me to scorn and misery!","literalText":true,"sourceStartIndex":216,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"springt vom Stein herab und tritt näher heran","translation":"jumps down from the stone and steps closer","literalText":true,"sourceStartIndex":219,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Die Nacht bricht an:\nin diesem Gemach\nmusst du dich mir vermählen!","translation":"Night falls:\nin this room\nYou must marry me!","literalText":true,"sourceStartIndex":220,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"indem sie den Finger, an dem sie Siegfrieds Ring trägt, drohend ausstreckt","translation":"by threateningly extending the finger on which she wears Siegfried's ring","literalText":true,"sourceStartIndex":223,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Bleib' fern! Fürchte dies Zeichen!\nZur Schande zwingst du mich nicht,\nsolang' der Ring mich beschützt.","translation":"Stay away! Fear this sign!\nYou will not bring me to shame,\nas long as the ring protects me.","literalText":true,"sourceStartIndex":224,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mannesrecht gebe er Gunther,\ndurch den Ring sei ihm vermählt!","translation":"He gave Gunther manly rights\nMay he be wedded to her through the ring!","literalText":true,"sourceStartIndex":227,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Zurück, du Räuber!\nFrevelnder Dieb!\nErfreche dich nicht, mir zu nahn!\nStärker als Stahl macht mich der Ring:\nnie - raubst du ihn mir!","translation":"Back off, you robber!\nOutrageous thief!\nDo not presume to approach me!\nThe ring makes me stronger than steel:\nNever - you'll steal him from me!","literalText":true,"sourceStartIndex":229,"sourceLineCount":5},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Von dir ihn zu lösen,\nlehrst du mich nun!","translation":"To release him from you\nAre you going to teach me now?","literalText":true,"sourceStartIndex":234,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er dringt auf sie ein; sie ringen miteinander. Brünnhilde windet sich los, flieht und wendet sich um, wie zur Wehr. Siegfried greift sie von neuem an. Sie flieht, er erreicht sie. Beide ringen heftig miteinander. Er fasst sie bei der Hand und entzieht ihrem Finger den Ring. Sie schreit heftig auf. Als sie wie zerbrochen in seinen Armen niedersinkt, streift ihr Blick bewusstlos die Augen Siegfrieds\nlässt die Machtlose auf die Steinbank vor dem Felsengemach niedergleiten","translation":"He presses her; they wrestle. Brünnhilde twists free, flees, and turns around as if in defense. Siegfried attacks her again. She flees, he catches her. They wrestle fiercely. He seizes her hand and pulls the ring from her finger. She cries out. As she collapses, broken, in his arms, her unconscious gaze meets Siegfried's.\nThe powerless woman slides down onto the stone bench in front of the rock chamber.","literalText":true,"sourceStartIndex":236,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Jetzt bist du mein,\nBrünnhilde, Gunthers Braut. -\nGönne mir nun dein Gemach!","translation":"Now you are mine,\nBrünnhilde, Gunther's bride.\nGrant me your room now!","literalText":true,"sourceStartIndex":238,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"starrt ohnmächtig vor sich hin, matt","translation":"stares blankly ahead, listless","literalText":true,"sourceStartIndex":241,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Was könntest du wehren, elendes Weib!","translation":"What could you possibly defend yourself against, you wretched woman!","literalText":true,"sourceStartIndex":242,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried treibt sie mit einer gebietenden Bewegung an. Zitternd und wankenden Schrittes geht sie in das Gemach\ndas Schwert ziehend, mit seiner natürlichen Stimme","translation":"Siegfried urges her on with a commanding gesture. Trembling and unsteady, she enters the chamber.\ndrawing his sword, in his natural voice","literalText":true,"sourceStartIndex":243,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Nun, Notung, zeuge du,\ndass ich in Züchten warb.\nDie Treue wahrend dem Bruder,\ntrenne mich von seiner Braut!","translation":"Well, Nottung, you bear witness,\nthat I advertised in breeding programs.\nLoyalty to one's brother,\nI'm breaking up with his bride!","literalText":true,"sourceStartIndex":245,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er folgt Brünnhilde\nDer Vorhang fällt","translation":"He follows Brünnhilde\nThe curtain falls","literalText":true,"sourceStartIndex":249,"sourceLineCount":2}]}]}];
